// currencyInfo is how people write a currency's symbol and how many decimals its minor unit has.
type currencyInfo struct {
	symbol   string
	decimals int
}

var currencies = map[Currency]currencyInfo{
	USD: {"$", 2},
	EUR: {"€", 2},
	GBP: {"£", 2},
	JPY: {"¥", 0},
	KWD: {"KWD ", 3},
}

// Valid reports whether c is a currency Tally bills in.
func (c Currency) Valid() bool {
	_, ok := currencies[c]
	return ok
}

// MinorUnits is the number of decimal places in c's minor unit: 2 for USD, 0 for JPY, 3 for KWD. It is 0 for an unknown
// currency.
func (c Currency) MinorUnits() int {
	return currencies[c].decimals
}

// ErrInvalidAmount is returned for an amount that cannot be read.
var ErrInvalidAmount = errors.New("invalid amount")

// ParseMajor reads an amount a person typed in major units ("12.50", "7", "1.250") and returns it in minor units. It takes at
// most c's MinorUnits decimals, and no decimal point at all for a currency without decimals.
func ParseMajor(s string, c Currency) (int64, error) {
	if !c.Valid() {
		return 0, fmt.Errorf("%w: unknown currency %q", ErrInvalidAmount, c)
	}
	s = strings.TrimSpace(s)
	decimals := c.MinorUnits()
	whole, frac, hasDot := strings.Cut(s, ".")
	if whole == "" || (hasDot && frac == "") || len(frac) > decimals {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	for _, r := range whole + frac {
		if r < '0' || r > '9' {
			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
		}
	}
	for len(frac) < decimals {
		frac += "0"
	}
	n, err := strconv.ParseInt(whole+frac, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	return n, nil
}

// Format renders an amount for people with c's decimals: "$1,234.50", "-€0.99", "¥1,000", "KWD 1.250".
func Format(amount int64, c Currency) string {
	sign, whole, frac := split(amount, c)
	return sign + currencies[c].symbol + group(whole) + frac
}

// FormatMajor renders an amount in major units with c's decimals and no thousands separator: "12.50", "1000", "1.250". It is
// the form ParseMajor reads.
func FormatMajor(amount int64, c Currency) string {
	sign, whole, frac := split(amount, c)
	return sign + strconv.FormatInt(whole, 10) + frac
}

// split separates an amount into its sign, its whole major units and its fraction: ".50" for USD, "" for JPY.
func split(amount int64, c Currency) (sign string, whole int64, frac string) {
	if amount < 0 {
		sign, amount = "-", -amount
	}
	decimals := c.MinorUnits()
	if decimals == 0 {
		return sign, amount, ""
	}
	scale := int64(1)
	for i := 0; i < decimals; i++ {
		scale *= 10
	}
	return sign, amount / scale, fmt.Sprintf(".%0*d", decimals, amount%scale)
}

