data.output:
1	// Package money handles amounts of money. An amount is an int64 count of its currency's minor unit (cents for USD), never a
2	// float.
3	package money
4	
5	import (
6		"errors"
7		"fmt"
8		"strconv"
9		"strings"
10	)
11	
12	// Currency is an ISO 4217 currency code.
13	type Currency string
14	
15	// The currencies Tally bills in.
16	const (
17		USD Currency = "USD"
18		EUR Currency = "EUR"
19		GBP Currency = "GBP"
20		JPY Currency = "JPY"
21		KWD Currency = "KWD"
22	)
23	
24	// currencyInfo is how people write a currency's symbol and how many decimals its minor unit has.
25	type currencyInfo struct {
26		symbol   string
27		decimals int
28	}
29	
30	var currencies = map[Currency]currencyInfo{
31		USD: {"$", 2},
32		EUR: {"€", 2},
33		GBP: {"£", 2},
34		JPY: {"¥", 0},
35		KWD: {"KWD ", 3},
36	}
37	
38	// Valid reports whether c is a currency Tally bills in.
39	func (c Currency) Valid() bool {
40		_, ok := currencies[c]
41		return ok
42	}
43	
44	// MinorUnits is the number of decimal places in c's minor unit: 2 for USD, 0 for JPY, 3 for KWD. It is 0 for an unknown
45	// currency.
46	func (c Currency) MinorUnits() int {
47		return currencies[c].decimals
48	}
49	
50	// ErrInvalidAmount is returned for an amount that cannot be read.
51	var ErrInvalidAmount = errors.New("invalid amount")
52	
53	// ParseMajor reads an amount a person typed in major units ("12.50", "7", "1.250") and returns it in minor units. It takes at
54	// most c's MinorUnits decimals, and no decimal point at all for a currency without decimals.
55	func ParseMajor(s string, c Currency) (int64, error) {
56		if !c.Valid() {
57			return 0, fmt.Errorf("%w: unknown currency %q", ErrInvalidAmount, c)
58		}
59		s = strings.TrimSpace(s)
60		decimals := c.MinorUnits()
61		whole, frac, hasDot := strings.Cut(s, ".")
62		if whole == "" || (hasDot && frac == "") || len(frac) > decimals {
63			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
64		}
65		for _, r := range whole + frac {
66			if r < '0' || r > '9' {
67				return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
68			}
69		}
70		for len(frac) < decimals {
71			frac += "0"
72		}
73		n, err := strconv.ParseInt(whole+frac, 10, 64)
74		if err != nil {
75			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
76		}
77		return n, nil
78	}
79	
80	// Format renders an amount for people with c's decimals: "$1,234.50", "-€0.99", "¥1,000", "KWD 1.250".
81	func Format(amount int64, c Currency) string {
82		sign, whole, frac := split(amount, c)
83		return sign + currencies[c].symbol + group(whole) + frac
84	}
85	
86	// FormatMajor renders an amount in major units with c's decimals and no thousands separator: "12.50", "1000", "1.250". It is
87	// the form ParseMajor reads.
88	func FormatMajor(amount int64, c Currency) string {
89		sign, whole, frac := split(amount, c)
90		return sign + strconv.FormatInt(whole, 10) + frac
91	}
92	
93	// split separates an amount into its sign, its whole major units and its fraction: ".50" for USD, "" for JPY.
94	func split(amount int64, c Currency) (sign string, whole int64, frac string) {
95		if amount < 0 {
96			sign, amount = "-", -amount
97		}
98		decimals := c.MinorUnits()
99		if decimals == 0 {
100			return sign, amount, ""
101		}
102		scale := int64(1)
103		for i := 0; i < decimals; i++ {
104			scale *= 10
105		}
106		return sign, amount / scale, fmt.Sprintf(".%0*d", decimals, amount%scale)
107	}
108	
109	// group writes n with a comma between each group of three digits.
110	func group(n int64) string {
111		s := strconv.FormatInt(n, 10)
112		var b strings.Builder
113		for i, r := range s {
114			if i > 0 && (len(s)-i)%3 == 0 {
115				b.WriteByte(',')
116			}
117			b.WriteRune(r)
118		}
119		return b.String()
120	}
121	
122	// Percent returns pct percent of amount, rounded half away from zero to a whole minor unit.
123	func Percent(amount int64, pct int) int64 { return divRound(amount*int64(pct), 100) }
124	
125	// BasisPoints returns bp basis points (hundredths of a percent) of amount, rounded half away from zero.
126	func BasisPoints(amount int64, bp int) int64 { return divRound(amount*int64(bp), 10000) }
127	
128	// divRound divides and rounds half away from zero.
129	func divRound(num, den int64) int64 {
130		if (num < 0) != (den < 0) {
131			return -((abs(num) + abs(den)/2) / abs(den))
132		}
133		return (abs(num) + abs(den)/2) / abs(den)
134	}
135	
136	func abs(v int64) int64 {
137		if v < 0 {
138			return -v
139		}
140		return v
141	}
