12	// planView is a plan with its price in major units ("12.50", "1000" for JPY) and formatted for people ("$12.50").
13	type planView struct {
14		store.Plan
15		Price          string `json:"price"`
16		PriceFormatted string `json:"price_formatted"`
17	}
18	
19	func viewPlan(p store.Plan) planView {
20		return planView{Plan: p, Price: money.FormatMajor(p.UnitAmount, p.Currency), PriceFormatted: money.Format(p.UnitAmount, p.Currency)}
21	}
22	
23	func (s *Server) listPlans(w http.ResponseWriter, r *http.Request, p auth.Principal) {
24		items := []planView{}
25		for _, pl := range s.store.Plans(p.OrgID) {
26			items = append(items, viewPlan(pl))
27		}
28		writeJSON(w, http.StatusOK, list{Items: items})
29	}
