31	// createPlan takes the price in major units, as a string ("12.50"), the way people type it.
32	func (s *Server) createPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
33		var in struct {
34			Name      string          `json:"name"`
35			Currency  money.Currency  `json:"currency"`
36			Price     string          `json:"price"`
37			Interval  store.Interval  `json:"interval"`
38			UsageType store.UsageType `json:"usage_type"`
39			TrialDays int             `json:"trial_days"`
40		}
41		if !decode(w, r, &in) {
42			return
43		}
44		amount, err := money.ParseMajor(in.Price, in.Currency)
45		if err != nil {
46			if errors.Is(err, money.ErrInvalidAmount) {
47				writeError(w, http.StatusUnprocessableEntity, "invalid_amount", err.Error())
48				return
49			}
50			s.storeError(w, err)
51			return
52		}
53		pl, err := s.store.CreatePlan(store.Plan{OrgID: p.OrgID, Name: in.Name, Currency: in.Currency, UnitAmount: amount, Interval: in.Interval,
54			UsageType: in.UsageType, TrialDays: in.TrialDays}, s.clock.Now())
55		if err != nil {
56			s.storeError(w, err)
57			return
58		}
59		writeJSON(w, http.StatusCreated, viewPlan(pl))
60	}
61	
62	func (s *Server) getPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
63		pl, ok := s.store.Plan(p.OrgID, r.PathValue("id"))
64		if !ok {
65			writeError(w, http.StatusNotFound, "not_found", "no such plan")
66			return
67		}
68		writeJSON(w, http.StatusOK, viewPlan(pl))
69	}
70	
71	func (s *Server) updatePlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
72		var in struct {
73			Name   *string `json:"name"`
74			Active *bool   `json:"active"`
75		}
76		if !decode(w, r, &in) {
77			return
78		}
79		pl, err := s.store.UpdatePlan(p.OrgID, r.PathValue("id"), func(pl *store.Plan) error {
80			if in.Name != nil {
81				pl.Name = *in.Name
82			}
83			if in.Active != nil {
84				pl.Active = *in.Active
85			}
86			return nil
87		})
88		if err != nil {
89			s.storeError(w, err)
90			return
91		}
92		writeJSON(w, http.StatusOK, viewPlan(pl))
93	}
