1	package api
2	
3	import (
4		"errors"
5		"fmt"
6		"net/http"
7		"strings"
8	
9		"example.com/tally/internal/auth"
10		"example.com/tally/internal/billing"
11		"example.com/tally/internal/money"
12		"example.com/tally/internal/payments"
13		"example.com/tally/internal/store"
14	)
15	
16	// invoiceView is an invoice as the API shows it: with its totals, a one-line description and its customer.
17	type invoiceView struct {
18		store.Invoice
19		billing.Totals
20		TotalFormatted string       `json:"total_formatted"`
21		Description    string       `json:"description"`
22		Customer       *customerRef `json:"customer"`
23	}
24	
25	// customerRef is the customer shown on an invoice; null when the customer was deleted.
26	type customerRef struct {
27		ID    string `json:"id"`
28		Name  string `json:"name"`
29		Email string `json:"email"`
30	}
31	
32	func newInvoiceView(inv store.Invoice, c *store.Customer) invoiceView {
33		t := billing.Compute(inv)
34		v := invoiceView{Invoice: inv, Totals: t, TotalFormatted: money.Format(t.Total, inv.Currency), Description: describe(inv.Lines)}
35		if c != nil {
36			v.Customer = &customerRef{ID: c.ID, Name: c.Name, Email: c.Email}
37		}
38		return v
39	}
40	
41	// describe is the invoice's first line, and how many more there are.
42	func describe(lines []store.Line) string {
43		d := lines[0].Description
44		if len(lines) > 1 {
45			d += fmt.Sprintf(" and %d more", len(lines)-1)
46		}
47		return d
48	}
49	
50	func (s *Server) viewInvoice(inv store.Invoice) invoiceView {
51		if c, ok := s.store.Customer(inv.OrgID, inv.CustomerID); ok {
52			return newInvoiceView(inv, &c)
53		}
54		return newInvoiceView(inv, nil)
55	}
56	
57	func findCustomer(cs []store.Customer, id string) *store.Customer {
58		for i := range cs {
59			if cs[i].ID == id {
60				return &cs[i]
61			}
62		}
63		return nil
64	}
65	
66	func invoiceViewKey(v invoiceView) cursor { return cursor{T: v.CreatedAt, ID: v.ID} }
67	
68	// listInvoices lists the organization's invoices, oldest first, optionally only those of ?customer_id=, ?subscription_id=
69	// or with ?status=.
70	func (s *Server) listInvoices(w http.ResponseWriter, r *http.Request, p auth.Principal) {
71		pg, ok := parsePage(w, r)
72		if !ok {
73			return
74		}
75		q := r.URL.Query()
76		status := store.InvoiceStatus(q.Get("status"))
77		if status != "" && status != store.InvoiceOpen && status != store.InvoicePaid && status != store.InvoiceVoid {
78			writeError(w, http.StatusBadRequest, "invalid_status", "status is open, paid or void")
79			return
80		}
81		invs := s.store.ListInvoices(p.OrgID, store.InvoiceFilter{CustomerID: q.Get("customer_id"), SubscriptionID: q.Get("subscription_id"), Status: status})
82		customers := s.store.Customers(p.OrgID)
83		views := make([]invoiceView, 0, len(invs))
84		for _, inv := range invs {
85			views = append(views, newInvoiceView(inv, findCustomer(customers, inv.CustomerID)))
86		}
87		items, next := pageOf(views, invoiceViewKey, pg)
88		writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
89	}
90	
91	func (s *Server) createInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
92		var in struct {
93			CustomerID      string         `json:"customer_id"`
94			Currency        money.Currency `json:"currency"`
95			Lines           []store.Line   `json:"lines"`
96			DiscountPercent int            `json:"discount_percent"`
97		}
98		if !decode(w, r, &in) {
99			return
100		}
101		if len(in.Lines) == 0 {
102			writeError(w, http.StatusUnprocessableEntity, "invalid", "an invoice needs at least one line")
103			return
104		}
105		for _, l := range in.Lines {
106			if strings.TrimSpace(l.Description) == "" || l.Quantity <= 0 || l.UnitAmount < 0 {
107				writeError(w, http.StatusUnprocessableEntity, "invalid", "each line needs a description, a positive quantity and a unit amount that is not negative")
108				return
109			}
110		}
111		inv, err := s.store.CreateInvoice(store.Invoice{OrgID: p.OrgID, CustomerID: in.CustomerID, Currency: in.Currency, Lines: in.Lines, DiscountPercent: in.DiscountPercent}, s.clock.Now())
112		if err != nil {
113			if errors.Is(err, store.ErrCustomerOrgMismatch) {
114				writeError(w, http.StatusUnprocessableEntity, "customer_org_mismatch", fmt.Sprintf("customer %s belongs to another organization", in.CustomerID))
115				return
116			}
117			s.storeError(w, err)
118			return
119		}
120		s.publish(r.Context(), p.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID})
121		writeJSON(w, http.StatusCreated, s.viewInvoice(inv))
122	}
123	
124	func (s *Server) getInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
125		inv, ok := s.store.Invoice(p.OrgID, r.PathValue("id"))
126		if !ok {
127			writeError(w, http.StatusNotFound, "not_found", "no such invoice")
128			return
129		}
130		writeJSON(w, http.StatusOK, s.viewInvoice(inv))
131	}
132	
133	// getInvoiceLines answers an invoice's lines with each line's amount, for the dashboard's invoice table.
134	func (s *Server) getInvoiceLines(w http.ResponseWriter, r *http.Request, p auth.Principal) {
135		inv, ok := s.store.InvoiceByID(r.PathValue("id"))
136		if !ok {
137			writeError(w, http.StatusNotFound, "not_found", "no such invoice")
138			return
139		}
140		type lineView struct {
141			store.Line
142			Amount int64 `json:"amount"`
143		}
144		items := []lineView{}
145		for _, l := range inv.Lines {
146			items = append(items, lineView{Line: l, Amount: l.Amount()})
147		}
148		writeJSON(w, http.StatusOK, list{Items: items})
149	}
150	
151	// payInvoice charges an invoice: {"payment_method": "pm_..."}, or the customer's default payment method when it is absent.
152	func (s *Server) payInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
153		var in struct {
154			PaymentMethod string `json:"payment_method"`
155		}
156		if r.ContentLength != 0 && !decode(w, r, &in) {
157			return
158		}
159		inv, pay, err := s.pay.Pay(r.Context(), p.OrgID, r.PathValue("id"), in.PaymentMethod)
160		if err != nil {
161			s.payError(w, err)
162			return
163		}
164		writeJSON(w, http.StatusOK, map[string]any{"invoice": s.viewInvoice(inv), "payment": pay})
165	}
166	
167	func (s *Server) payError(w http.ResponseWriter, err error) {
168		var decline *payments.DeclineError
169		switch {
170		case errors.As(err, &decline):
171			writeJSON(w, http.StatusPaymentRequired, map[string]string{"error": "payment_declined", "decline_code": decline.Code, "message": err.Error()})
172		case errors.Is(err, payments.ErrAlreadyPaid):
173			writeError(w, http.StatusConflict, "already_paid", err.Error())
174		case errors.Is(err, payments.ErrInvoiceVoid):
175			writeError(w, http.StatusConflict, "invoice_void", err.Error())
176		case errors.Is(err, payments.ErrNoPaymentMethod):
177			writeError(w, http.StatusUnprocessableEntity, "no_payment_method", err.Error())
178		case errors.Is(err, payments.ErrUnavailable):
179			writeError(w, http.StatusServiceUnavailable, "gateway_unavailable", "the payment gateway is unavailable; nothing was charged, try again")
180		default:
181			s.storeError(w, err)
182		}
